    usage = None
    usage_elem = ev_elem.find("usage")
    if usage_elem is not None and usage_elem.text:
        usage = usage_elem.text.strip()
    values = []
    for val_elem in ev_elem.findall("enumeratedValue"):
        n_elem = val_elem.find("name")
        if n_elem is None or not (n_elem.text or "").strip():
            continue
        vname = (n_elem.text or "").strip()
        d_elem = val_elem.find("description")
        vdesc = (d_elem.text or "").strip() if d_elem is not None and d_elem.text else ""
        # value: <value> tag with number? Or <isDefault>? Handle.
        vval = None
        is_default = False
        val_tag = val_elem.find("value")
        if val_tag is not None and (val_tag.text or "").strip() != "":
            try:
                vval = parse_svd_number((val_tag.text or "").strip(), "value")
            except:
                vval = 0
        else:
            # Check isDefault?
            isdef_elem = val_elem.find("isDefault")
            if isdef_elem is not None and (isdef_elem.text or "").strip().lower() == "true":
                is_default = True
                vval = None  # default? What value? Untested. For default, value is don't care? In codegen, default variant? Handle later.
            else:
                vval = 0
        values.append(SvdEnumeratedValue(vname, vdesc, vval, is_default))
    derived_from = ev_elem.get("derivedFrom")
    if derived_from is None:
        df_elem = ev_elem.find("derivedFrom")
        if df_elem is not None and df_elem.text:
            derived_from = df_elem.text.strip()
    return SvdEnumeratedValues(name, usage, values, derived_from)

